fn element_wise_modulo(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Check if both arrays have the same length
    assert_eq!(a.len(), b.len(), "Input arrays must have the same length");
    
    // Create a new vector to store the results
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through the elements of both arrays
    for i in 0..a.len() {
        // Since we assume b[i] is non-zero, we can safely perform the modulo operation
        result.push(a[i] % b[i]);
    }
    
    result
}